import{_ as t,o,c as l,a5 as r}from"./chunks/framework.DJo0M80U.js";const y=JSON.parse('{"title":"返回函数计算属性原理","description":"在 Vue 中，如果一个计算属性返回一个函数（如 computed(() \\\\ (param) \\\\ \\\\{...\\\\})），以下是关键点： 1. 缓存的是函数本身 ： 计算属性的缓存机制作用于返回的函数对象。当依赖（如 tradeType.value 或 props）不变时，Vue 缓。","frontmatter":{"title":"返回函数计算属性原理","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在 Vue 中，如果一个计算属性返回一个函数（如 computed(() \\\\ (param) \\\\ \\\\{...\\\\})），以下是关键点： 1. 缓存的是函数本身 ： 计算属性的缓存机制作用于返回的函数对象。当依赖（如 tradeType.value 或 props）不变时，Vue 缓。","sidebarWeight":60,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/计算属性/返回函数计算属性原理.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/计算属性/返回函数计算属性原理.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/计算属性/返回函数计算属性原理.md"}'),s={name:"posts/Vue系统教程/02-模板、组件与交互/计算属性/返回函数计算属性原理.md"};function p(a,e,i,u,d,n){return o(),l("div",null,[...e[0]||(e[0]=[r('<div><h1 id="返回函数计算属性原理" tabindex="-1">返回函数计算属性原理 <a class="header-anchor" href="#返回函数计算属性原理" aria-label="Permalink to &quot;返回函数计算属性原理&quot;">​</a></h1><blockquote><p>本节目标：理解“返回函数计算属性原理”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 中，如果一个计算属性返回一个函数（如 computed(() =&gt; (param) =&gt; {...})），以下是关键点：</p></blockquote><ol><li><strong>缓存的是函数本身</strong>： <ul><li>计算属性的缓存机制作用于返回的函数对象。当依赖（如 tradeType.value 或 props）不变时，Vue 缓存的是同一个函数实例，不会重新生成新的函数。</li><li>例如，在你的例子中，getStyle 计算属性返回的函数对象在依赖不变时始终是同一个。</li></ul></li><li><strong>函数调用仍然会执行</strong>： <ul><li>每次在模板中调用 getStyle(type)（如在 v-for 中），函数的内部逻辑都会执行，因为函数调用本身不被缓存。计算属性的缓存只保证返回的函数是同一个实例，但调用函数时仍会根据传入的参数（type）重新计算结果。</li><li>换句话说，缓存的是 getStyle 的返回值（即函数本身），而不是 getStyle(type) 的调用结果。</li></ul></li><li><strong>与普通方法的区别</strong>： <ul><li>如果你用普通方法（methods）定义 getStyle(type)，每次调用都会完整执行逻辑，且没有缓存。</li><li>用计算属性返回函数，虽然函数调用本身会执行，但函数的创建和依赖的响应式更新被缓存，适合依赖响应式数据的场景。</li></ul></li></ol><p><strong>验证你的理解</strong></p><ul><li><strong>缓存</strong>：当 tradeType.value、props.askColor 或 props.bidColor 不变时，getStyle 返回的函数是缓存的同一个函数实例。</li><li><strong>执行</strong>：在模板渲染时，如 &lt;div :style=&quot;getStyle(type)&quot;&gt;，每次调用 getStyle(type) 都会执行函数内部逻辑，计算基于 type 的样式对象。</li></ul><p><strong>示例说明</strong> &lt;script setup lang=&quot;ts&quot;&gt;import { computed } from &#39;vue&#39;import { TradeType } from &#39;@/enum&#39; const tradeType = defineModel&lt;TradeType&gt;(&#39;tradeType&#39;)const props = defineProps&lt;{ bidColor: string; askColor: string }&gt;() const getStyle = computed(() =&gt; { console.log(&#39;getStyle computed ran&#39;) <em>// 仅在依赖变化时触发</em> return (type: TradeType) =&gt; { console.log(<code>getStyle called with ${type}</code>) <em>// 每次调用都会触发</em> const isSelected = type === tradeType.value return { color: isSelected ? &#39;white&#39; : type === &#39;sell&#39; ? props.askColor : props.bidColor, backgroundColor: isSelected ? (type === &#39;sell&#39; ? props.askColor : props.bidColor) : &#39;white&#39;, } }})&lt;/script&gt; &lt;template&gt; &lt;div v-for=&quot;type in Object.values(TradeType)&quot; :style=&quot;getStyle(type)&quot;&gt; {{ type }} &lt;/div&gt;&lt;/template&gt; <strong>运行时表现：</strong></p><ul><li>初次渲染或依赖（如 tradeType.value）变化时，getStyle computed ran 打印一次，表明计算属性重新计算并返回新函数。</li><li>每次 v-for 渲染时，getStyle called with ${type} 会为每个 type 打印，表明函数调用仍然执行。</li></ul><p><strong>如何进一步优化</strong> 如果你希望连函数调用的结果也缓存（而不仅是函数本身），可以改用对象形式的计算属性，如之前的 styleMap 示例： const styleMap = computed(() =&gt; { const result: Record&lt;TradeType, { color: string; backgroundColor: string }&gt; = {} as any Object.values(TradeType).forEach((type) =&gt; { const isSelected = type === tradeType.value result[type] = { color: isSelected ? &#39;white&#39; : type === &#39;sell&#39; ? props.askColor : props.bidColor, backgroundColor: isSelected ? (type === &#39;sell&#39; ? props.askColor : props.bidColor) : &#39;white&#39;, } }) return result})</p><ul><li><strong>模板使用</strong>：:style=&quot;styleMap[type]&quot;</li><li><strong>优势</strong>：styleMap 缓存了所有 type 的样式对象，调用 styleMap[type] 直接返回缓存结果，不需要每次执行函数逻辑。</li></ul></div>',1)])])}const c=t(s,[["render",p]]);export{y as __pageData,c as default};
